// Three-band guard: keep >= 0.7, keep-but-rank-lower 0.3-0.7, drop < 0.3.
// Enough = Jev is confident the results already hold 5 good restaurants.
const KEEP_AT = 0.7, DROP_BELOW = 0.3, SUFFICIENT_AT = 0.7, MIN_STRONG = 3;
const items = <screeninstant.result.items> || [];
const ans = <jevinstantguard.answers> || {};
const r3 = v => Math.round(v * 1000) / 1000;
const scored = items.map((it, i) => {
  const v = ans['result_' + (i + 1)] && ans['result_' + (i + 1)].noul;
  const p = typeof v === 'number' && Number.isFinite(v) ? r3(v) : 0.5;
  return Object.assign({}, it, { jevRelevance: p, band: p >= KEEP_AT ? 'keep' : (p >= DROP_BELOW ? 'uncertain' : 'drop') });
});
const byP = (a, b) => b.jevRelevance - a.jevRelevance;
const strong = scored.filter(x => x.band === 'keep').sort(byP);
const uncertain = scored.filter(x => x.band === 'uncertain').sort(byP);
